mapper.select:
SELECT co.owner_name as ownerName, pb.name as brandName, p.* FROM wms_products p LEFT JOIN wms_cargo_owners co ON p.owner_id = co.id LEFT JOIN wms_product_brand pb ON p.product_brand = pb.id WHERE p.status = '1' -- 只查询启用状态的商品
AND p.owner_id = #{wmsProducts.ownerId}
AND p.product_code LIKE concat('%',#{wmsProducts.productCode},'%')
